import{_ as t,o as r,c as a,ai as o}from"./chunks/framework.ampVZV4B.js";const g=JSON.parse('{"title":"1. 基础原理","description":"","frontmatter":{},"headers":[],"relativePath":"redis/01-basics.md","filePath":"redis/01-basics.md"}'),s={name:"redis/01-basics.md"};function d(i,e,l,n,h,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="_1-基础原理" tabindex="-1">1. 基础原理 <a class="header-anchor" href="#_1-基础原理" aria-label="Permalink to “1. 基础原理”">​</a></h1><p>目标：能用 1～2 分钟讲清「Redis 是什么、为什么快、线程模型怎么演进」，并落到生产注意点。</p><hr><h2 id="redis-是什么" tabindex="-1">Redis 是什么 <a class="header-anchor" href="#redis-是什么" aria-label="Permalink to “Redis 是什么”">​</a></h2><p>基于<strong>内存</strong>的高性能键值存储。除 String / Hash / List / Set / ZSet，还有过期、持久化、Pub/Sub、Stream、Lua、弱事务等。</p><p>我在项目里主要当：</p><ul><li><strong>缓存层</strong>（热点读）</li><li><strong>分布式协调</strong>（锁、限流、计数）</li><li><strong>临时状态</strong>（登录会话、验证码、短时标记）</li></ul><p>不是替代 MySQL 的持久业务库。</p><hr><h2 id="为什么快-口述四条" tabindex="-1">为什么快（口述四条） <a class="header-anchor" href="#为什么快-口述四条" aria-label="Permalink to “为什么快（口述四条）”">​</a></h2><ol><li><strong>内存访问</strong>，避免磁盘随机 IO</li><li><strong>高效数据结构</strong>（如 SDS、跳表、压缩结构按量切换）</li><li><strong>I/O 多路复用</strong>，单线程处理命令也能撑高并发连接</li><li><strong>命令简单</strong>，多数 O(1) / O(log N)，避免复杂查询计划</li></ol><p>加分：快不等于无限快——<strong>大 Key、热 Key、慢命令、网卡</strong>都会拖垮体感。</p><hr><h2 id="单线程-多线程" tabindex="-1">单线程 / 多线程 <a class="header-anchor" href="#单线程-多线程" aria-label="Permalink to “单线程 / 多线程”">​</a></h2><p><strong>经典说法：</strong> Redis 执行命令的主线程是单线程的，所以单命令原子、无锁竞争。</p><p><strong>容易踩坑的理解：</strong></p><ul><li>「单线程」指<strong>命令执行</strong>，不是整个进程只有一个线程（还有 BIO 线程、Redis 6 的 I/O 线程等）</li><li>一个慢命令（大 Key 的 <code>HGETALL</code>、<code>KEYS *</code>）会堵住后续所有命令</li></ul><p><strong>优化：</strong> 禁 <code>KEYS</code>，用 <code>SCAN</code>；删大 Key 用 <code>UNLINK</code>；拆大 Key；耗时逻辑放应用或异步。</p><hr><h2 id="io-模型" tabindex="-1">IO 模型 <a class="header-anchor" href="#io-模型" aria-label="Permalink to “IO 模型”">​</a></h2><p>主线程用 <strong>epoll/kqueue 等多路复用</strong> 监听连接，可读时读入、解析、执行、写回。</p><p>连接再多，也是「一个线程轮询就绪事件」，所以并发连接成本远低于「一连接一线程」。</p><hr><h2 id="redis-6-之后的线程模型" tabindex="-1">Redis 6 之后的线程模型 <a class="header-anchor" href="#redis-6-之后的线程模型" aria-label="Permalink to “Redis 6 之后的线程模型”">​</a></h2><p>Redis 6+ 引入可选的 <strong>I/O 线程</strong>：把读 socket / 写 socket 等部分工作并行化，<strong>命令执行仍主要在主线程</strong>，保证单命令语义简单。</p><p>口述：</p><blockquote><p>6 之前瓶颈常在网络读写；6 之后可用多 I/O 线程提吞吐，但业务上仍要当成「命令串行执行」来设计，不能假设多个写命令在服务端并行交错执行同一逻辑。</p></blockquote><hr><h2 id="核心优化清单" tabindex="-1">核心优化清单 <a class="header-anchor" href="#核心优化清单" aria-label="Permalink to “核心优化清单”">​</a></h2><table tabindex="0"><thead><tr><th>点</th><th>做法</th></tr></thead><tbody><tr><td>慢命令</td><td>监控 <code>slowlog</code>；禁 <code>KEYS</code>；控制返回体积</td></tr><tr><td>大对象</td><td>拆 Key；分批删；<code>UNLINK</code></td></tr><tr><td>连接</td><td>连接池；避免每请求新建连接</td></tr><tr><td>版本</td><td>生产注明大版本；I/O 线程按压测开</td></tr></tbody></table><p>下一步：<a href="./data-types.html">数据结构</a> · <a href="./09-performance.html">性能</a></p>',31)])])}const b=t(s,[["render",d]]);export{g as __pageData,b as default};
